INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (63, 'Mesin tidak menyala atau sistem kontrol tidak aktif', 'Mesin tidak dapat melakukan proses otomatis dan sistem kontrol komputer tidak aktif.', 'Suplai listrik 380 V + N tidak tersedia, pemutus sirkuit aktif, koneksi listrik bermasalah, atau sistem kontrol belum mendapatkan daya.', 'Periksa keberadaan suplai listrik sesuai spesifikasi mesin dan kondisi pemutus sirkuit. Periksa koneksi daya hanya oleh personel yang berwenang.', 'Mesin menggunakan suplai 380 V + N. Matikan dan isolasikan sumber listrik sebelum pemeriksaan kelistrikan. Jangan membuka panel listrik tanpa personel yang kompeten.', 'Data spesifikasi MAICA UAM-02 dan panduan pemeriksaan umum mesin otomatis');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (63, 'Tekanan udara pneumatik tidak mencukupi', 'Aktuator pneumatik bergerak lemah, lambat, atau proses otomatis berhenti.', 'Tekanan udara di bawah kebutuhan 7 bar, suplai udara terganggu, atau terdapat kebocoran pada sistem pneumatik.', 'Periksa tekanan suplai udara dan pastikan berada pada kondisi kerja sesuai spesifikasi. Periksa selang dan sambungan yang dapat diakses untuk mengetahui adanya kebocoran.', 'Lepaskan tekanan udara sebelum membongkar komponen pneumatik. Jangan memasukkan tangan ke area aktuator saat sistem dapat bergerak otomatis.', 'Data spesifikasi MAICA UAM-02 dan panduan pemeriksaan umum sistem pneumatik');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (63, 'Sistem vacuum tidak bekerja dengan baik', 'Collar bone tidak terangkat, tidak tertahan, atau tidak berpindah ke posisi aplikasi dengan benar.', 'Vacuum tidak terbentuk, saluran vacuum tersumbat, sambungan bocor, atau komponen penangkap tidak bekerja dengan baik.', 'Periksa kondisi sistem vacuum, sambungan dan saluran yang dapat diakses. Bersihkan bagian yang dapat dibersihkan sesuai prosedur mesin dan pastikan objek dapat tertahan dengan stabil.', 'Matikan mesin dan pastikan gerakan otomatis berhenti sebelum memeriksa area vacuum dan mekanisme pengambil benda.', 'Data spesifikasi MAICA UAM-02 dan panduan pemeriksaan umum sistem vacuum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (63, 'Posisi pemasangan label tidak tepat', 'Label terpasang miring, bergeser, atau tidak berada pada posisi yang seharusnya.', 'Posisi material tidak tepat, sistem penempatan belum terkalibrasi, label tidak masuk pada posisi yang benar, atau sensor pendeteksi mengalami gangguan.', 'Periksa posisi material dan label, periksa sensor yang dapat diakses, lalu lakukan penyesuaian posisi atau kalibrasi melalui sistem kontrol sesuai prosedur mesin.', 'Hentikan siklus otomatis sebelum melakukan penyetelan pada area aplikasi label. Jangan menjangkau area mekanisme saat mesin siap melakukan siklus.', 'Data spesifikasi MAICA UAM-02 dan panduan pemeriksaan umum sistem aplikasi label');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (63, 'Collar bone tidak terpasang atau tidak berada pada posisi yang benar', 'Collar bone tidak terpasang sesuai posisi, bergeser, atau proses aplikasi berhenti sebelum selesai.', 'Supply collar bone tidak lancar, vacuum tidak stabil, posisi material tidak sesuai, atau mekanisme setter mengalami gangguan.', 'Periksa pasokan collar bone, sistem vacuum, posisi material, dan mekanisme setter. Jalankan pengujian menggunakan material yang sesuai setelah penyebab gangguan diperbaiki.', 'Matikan siklus otomatis sebelum mengambil material yang macet. Jangan memasukkan tangan ke area setter ketika aktuator masih dapat bergerak.', 'Data spesifikasi MAICA UAM-02 dan panduan pemeriksaan umum proses collar bone');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (63, 'Aplikasi beberapa label tidak berjalan sesuai program', 'Tidak semua label yang diprogram terpasang atau urutan aplikasi label tidak sesuai.', 'Program atau parameter aplikasi tidak sesuai, material tidak terdeteksi, sensor mengalami gangguan, atau salah satu tahap proses gagal.', 'Periksa program dan parameter melalui sistem kontrol komputer, periksa sensor dan posisi material, kemudian lakukan pengujian ulang secara bertahap.', 'Hentikan mesin sebelum melakukan perubahan pada mekanisme. Perubahan program harus dilakukan oleh operator yang memahami prosedur mesin.', 'Data spesifikasi MAICA UAM-02 dan panduan pemeriksaan umum sistem kontrol');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (63, 'Proses otomatis berhenti di tengah siklus', 'Mesin berhenti sebelum seluruh tahapan aplikasi label atau collar bone selesai.', 'Salah satu sensor tidak memberikan sinyal, tekanan udara atau vacuum tidak mencukupi, material macet, atau sistem kontrol mendeteksi kondisi abnormal.', 'Periksa pesan atau indikator pada sistem kontrol, kemudian periksa sensor, suplai udara, vacuum, dan posisi material sesuai urutan pemeriksaan.', 'Jangan melewati interlock atau sensor keselamatan untuk memaksa mesin bekerja. Pastikan sumber gerakan berbahaya berhenti sebelum pemeriksaan.', 'Data spesifikasi MAICA UAM-02 dan panduan pemeriksaan umum mesin otomatis');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (63, 'Stacker tidak menyelesaikan proses penumpukan', 'Produk yang telah diproses tidak tersusun atau berpindah ke bagian stacker dengan benar.', 'Aliran produk menuju stacker terganggu, sensor posisi tidak mendeteksi produk, tekanan udara tidak mencukupi, atau mekanisme stacker mengalami hambatan.', 'Periksa jalur perpindahan produk, sensor yang dapat diakses, suplai udara, dan area stacker dari material yang menghalangi. Uji kembali setelah area bebas hambatan.', 'Hentikan mesin sebelum mengambil material dari area stacker. Jangan menjangkau mekanisme stacker saat mesin masih dalam mode otomatis.', 'Data spesifikasi MAICA UAM-02 dan panduan pemeriksaan umum sistem stacker');
